mapper.select:

where s.del_flag = '0' and s.teacher_id = #{teacherId}
and s.schedule_id = #{scheduleId}
order by , s.grade_name, s.course_year desc, s.term_name, s.period_name, s.start_time, s.schedule_id


where s.del_flag = '0'
and s.grade_name = #{gradeName}
order by , s.grade_name, s.course_year desc, s.term_name, s.period_name, s.start_time, s.schedule_id
